{
  "name": "Zaber电动精密位移台",
  "name_en": "Zaber motorized positioning stage",
  "manufacturer": "Zaber Technologies",
  "description": "这是一种用于精密线性定位与自动运动控制的电动位移台或单轴运动平台，可通过串口二进制协议进行控制。它常用于实验室中的光学元件、样品台或探针的位置调整、回零、定点移动和自动扫描。",
  "description_en": "This is a motorized precision positioning stage or single-axis motion platform used for accurate linear positioning and automated motion control. It is commonly used in laboratories to position optical components, samples, or probes, including homing, point-to-point moves, and automated scanning.",
  "tag_hints": [
    "motorized positioning",
    "translation stage",
    "precision motion control",
    "optical alignment",
    "automated scanning",
    "serial control",
    "single-axis stage"
  ],
  "actions": [
    {
      "action_name": "auto-write",
      "description": "向设备写入二进制串口命令。",
      "description_en": "Write a binary serial command to the device."
    },
    {
      "action_name": "auto-read",
      "description": "读取设备返回的二进制串口响应。",
      "description_en": "Read a binary serial reply from the device."
    },
    {
      "action_name": "auto-flush",
      "description": "清空串口通信缓冲区。",
      "description_en": "Flush the serial communication buffers."
    },
    {
      "action_name": "auto-open",
      "description": "打开与设备的串口连接。",
      "description_en": "Open the serial connection to the device."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与设备的串口连接。",
      "description_en": "Close the serial connection to the device."
    },
    {
      "action_name": "auto-timeout",
      "description": "获取/设置串口读取超时时间。",
      "description_en": "Get/set the serial read timeout."
    },
    {
      "action_name": "auto-baudrate",
      "description": "获取/设置串口波特率。",
      "description_en": "Get/set the serial baud rate."
    },
    {
      "action_name": "auto-encode",
      "description": "将控制命令编码为Zaber二进制协议消息。",
      "description_en": "Encode a control command into a Zaber binary-protocol message."
    },
    {
      "action_name": "auto-send",
      "description": "向位移台发送控制命令。",
      "description_en": "Send a control command to the stage."
    },
    {
      "action_name": "auto-home",
      "description": "使位移台回到参考原点。",
      "description_en": "Home the stage to its reference position."
    },
    {
      "action_name": "auto-move_abs",
      "description": "将位移台移动到绝对位置。",
      "description_en": "Move the stage to an absolute position."
    },
    {
      "action_name": "auto-move_rel",
      "description": "使位移台按相对位移移动。",
      "description_en": "Move the stage by a relative displacement."
    },
    {
      "action_name": "auto-move_vel",
      "description": "使位移台以设定速度连续运动。",
      "description_en": "Move the stage continuously at a set velocity."
    },
    {
      "action_name": "auto-get_status",
      "description": "获取位移台状态。",
      "description_en": "Get the stage status."
    }
  ]
}

